import torch
from torch import nn


def encode(text):
    chars = sorted(set(text))
    index = {c: i for i, c in enumerate(chars)}
    return torch.tensor([index[c] for c in text], dtype=torch.long), chars


def train_bigram(ids, vocab, steps=300):
    model = nn.Embedding(vocab, vocab)
    optimizer = torch.optim.Adam(model.parameters(), lr=0.1)
    loss_fn = nn.CrossEntropyLoss()
    for step in range(steps):
        optimizer.zero_grad()
        loss_fn(model(ids[:-1]), ids[1:]).backward()
        optimizer.step()
    return model


def generate(model, chars, start, length):
    text = start
    index = {c: i for i, c in enumerate(chars)}
    with torch.no_grad():
        for _ in range(length):
            scores = model(torch.tensor([index[text[-1]]]))
            text += chars[scores.argmax(dim=-1).item()]
    return text

