import torch


def export_model(model, example):
    return torch.export.export(model, (example,))


def ops(ep):
    return [str(node.target) for node in ep.graph.nodes if node.op == "call_function"]


def run_batches(ep, x, batch):
    module = ep.module()
    outputs = []
    for start in range(0, len(x), batch):
        chunk = x[start:start + batch]
        real = len(chunk)
        if real < batch:
            chunk = torch.cat([chunk, torch.zeros(batch - real, *x.shape[1:])])
        outputs.append(module(chunk)[:real])
    return torch.cat(outputs)


def round_trip(ep, path):
    torch.export.save(ep, path)
    return torch.export.load(path)
